const data=await tools.Read({file_path:"/Users/anudeepbonagiri/dev/hackathons/dispatch-ledger/seed/fixtures/evidence/telematics/84.csv"});
if(typeof data!=="string") throw new Error("Expected CSV text");
const lines=data.trim().split("\n");
const records=lines.slice(1).map(line=>{const [truckId,at,lat,lon,engineOn,odometer]=line.split(","); const rad=Math.PI/180; const a=Math.sin((Number(lat)-28.0405)*rad/2)**2+Math.cos(28.0405*rad)*Math.cos(Number(lat)*rad)*Math.sin((Number(lon)+99.354)*rad/2)**2; return {line,truckId,at,distance_m:6371000*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))};});
const window=records.filter(r=>r.at>="2026-10-26T17:01:00Z"&&r.at<="2026-10-26T17:21:00Z").sort((a,b)=>a.distance_m-b.distance_m);
text({source:"telematics/84.csv",total_rows:records.length,window_rows:window.length,within_3000m:window.filter(r=>r.distance_m<3000),closest_window_rows:window.slice(0,5),truck26_near_transaction:records.filter(r=>r.truckId==="26"&&r.at>="2026-10-26T16:00:00Z"&&r.at<="2026-10-26T18:00:00Z"),closest_day_rows:[...records].sort((a,b)=>a.distance_m-b.distance_m).slice(0,5)});
